import { tool } from "ai";
import { sleep } from "workflow";
import { z } from "zod";

article.sections.7.blocks.2.text:
export async function runSleepCommand({
  timeoutMs,
}: {
  timeoutMs: number;
}) {
  await sleep(timeoutMs);
  return { status: "awake" as const };
}

article.sections.7.blocks.3.text:
export const sleepTool = tool({
  description: "Wait only when the user explicitly requests it.",
  inputSchema: z.object({
    timeoutMs: z.number().nonnegative(),
  }),
  execute: runSleepCommand,
});
```
